"""Install an isolated diagnostic-only mapped-view producer on the frozen paired source."""
import argparse
from pathlib import Path

PATH = Path("crates/victory-hle/src/modules/xmem.rs")
REPLACEMENTS = (
    ("    views: BTreeMap<usize, (usize, Slice)>,", "    views: BTreeMap<usize, (usize, Slice)>,\n    mapping_observation: mapping_diagnostic::Working,", 1),
    ("        next_page: 0x10_0000,\n        ..Default::default()", "        next_page: 0x10_0000,\n        mapping_observation: mapping_diagnostic::Working::new(mapping_diagnostic_on()),\n        ..Default::default()", 1),
    ("fn physical() -> MutexGuard<'static, Physical> {\n    PHYSICAL.lock().unwrap_or_else(|e| e.into_inner())\n}", "#[path = \"xmem_mapping_diagnostic.rs\"]\nmod mapping_diagnostic;\n\nstatic MAPPING_PUBLICATION: LazyLock<mapping_diagnostic::Publication> =\n    LazyLock::new(mapping_diagnostic::Publication::default);\n\nfn mapping_diagnostic_on() -> bool {\n    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();\n    cfg!(feature = \"diagnostics\") && *ON.get_or_init(|| std::env::var_os(\"VICTORY_MAPPING_DIAGNOSTIC\").is_some_and(|v| v == \"1\"))\n}\n\n// No new mutex. Drop publishes changed or uncertain mapping state\n// before the original guard unlocks PHYSICAL. No work for read-only/off.\nstruct PhysicalGuard(MutexGuard<'static, Physical>);\nimpl std::ops::Deref for PhysicalGuard {\n    type Target = Physical;\n    fn deref(&self) -> &Physical { &self.0 }\n}\nimpl std::ops::DerefMut for PhysicalGuard {\n    fn deref_mut(&mut self) -> &mut Physical { &mut self.0 }\n}\nimpl Drop for PhysicalGuard {\n    fn drop(&mut self) {\n        if !self.0.mapping_observation.needs_finish() { return; }\n        if let Some((bytes, valid)) = self.0.mapping_observation.take_completed(std::thread::panicking()) {\n            MAPPING_PUBLICATION.publish_serialized(bytes, self.0.shown.len() as u64, valid);\n        }\n    }\n}\nfn physical() -> PhysicalGuard {\n    PhysicalGuard(PHYSICAL.lock().unwrap_or_else(|e| e.into_inner()))\n}\n\n#[allow(dead_code)]\nfn mapping_diagnostic_snapshot() -> Result<mapping_diagnostic::Snapshot,mapping_diagnostic::Unavailable> {\n    if !mapping_diagnostic_on() { return Err(mapping_diagnostic::Unavailable::Disabled); }\n    MAPPING_PUBLICATION.sample()\n}", 1),
    ("    let exact = exact_placeholders_on() && physical.exact_placeholders.take(base, len);", "    physical.mapping_observation.begin();\n    let exact = exact_placeholders_on() && physical.exact_placeholders.take(base, len);", 1),
    ("        view = replace();", "        view = replace();\n        if !view.Value.is_null() && view.Value as usize != base { physical.mapping_observation.unknown(); }", 2),
    ("        unsafe { UnmapViewOfFile2(GetCurrentProcess(), view, MEM_PRESERVE_PLACEHOLDER) };", "        let rolled_back = unsafe { UnmapViewOfFile2(GetCurrentProcess(), view, MEM_PRESERVE_PLACEHOLDER) } != 0;\n        if !rolled_back { physical.mapping_observation.unknown(); }", 1),
    ("    physical.views.insert(base, (len, slice));", "    let replaced = physical.views.insert(base, (len, slice)).is_some();\n    physical.mapping_observation.inserted(len, replaced);", 1),
    ("        let unmapped = host_unmap(at);", "        physical.mapping_observation.begin();\n        let unmapped = host_unmap(at);", 1),
    ("        physical.views.remove(&at);", "        let removed = physical.views.remove(&at).is_some();\n        physical.mapping_observation.removed(size, removed);", 1),
    ("            if let Some(addresses) = physical.shown.get_mut(&key) {\n                addresses.retain(|&a| a != at + k * PAGE);\n                if addresses.is_empty() {\n                    physical.shown.remove(&key);\n                }\n            }", "            let reverse_ok = if let Some(addresses) = physical.shown.get_mut(&key) {\n                let before = addresses.len();\n                addresses.retain(|&a| a != at + k * PAGE);\n                let one_removed = before.checked_sub(addresses.len()) == Some(1);\n                if addresses.is_empty() {\n                    physical.shown.remove(&key);\n                }\n                one_removed\n            } else {\n                false\n            };\n            if !reverse_ok { physical.mapping_observation.unknown(); }", 1),
    ("    #[test]\n    fn physical_pages_map_alias_and_unmap() {", "    // Separate process per explicit mode: global PHYSICAL starts empty.\n    #[test]\n    #[ignore = \"isolated mapping diagnostic mode\"]\n    fn mapping_diagnostic_actual_views() {\n        use mapping_diagnostic::Unavailable;\n        let mode = std::env::var(\"VICTORY_MAPPING_DIAGNOSTIC\").expect(\"explicit diagnostic mode\");\n        assert!(matches!(mode.as_str(), \"0\" | \"1\"));\n        let enabled = mode == \"1\";\n        assert_eq!(mapping_diagnostic_on(), enabled);\n        // Bounded independent test-only reconstruction. No production scan.\n        let oracle = |bytes: usize, unique: usize| {\n            let guard = physical();\n            assert!(guard.views.len() <= 8 && guard.shown.len() <= 8);\n            let mut expected = BTreeMap::<(usize, usize), Vec<usize>>::new();\n            let mut total = 0usize;\n            let mut previous_end = 0usize;\n            for (&base, (len, slice)) in &guard.views {\n                assert!(base % PAGE == 0 && *len != 0 && *len % PAGE == 0);\n                assert!(base >= previous_end && *len / PAGE <= 8);\n                previous_end = base.checked_add(*len).expect(\"view end\");\n                total = total.checked_add(*len).expect(\"view bytes\");\n                assert!(total <= 8 * PAGE);\n                for k in 0..(*len / PAGE) {\n                    let key = (Arc::as_ptr(&slice.section) as usize,\n                               slice.index.checked_add(k).expect(\"page index\"));\n                    expected.entry(key).or_default().push(base + k * PAGE);\n                }\n            }\n            let mut actual = BTreeMap::new();\n            for (&key, addresses) in &guard.shown {\n                assert!(!addresses.is_empty() && addresses.len() <= 8);\n                let mut sorted = addresses.clone();\n                sorted.sort_unstable();\n                assert!(sorted.windows(2).all(|w| w[0] != w[1]), \"duplicate reverse entry\");\n                actual.insert(key, sorted);\n            }\n            for addresses in expected.values_mut() { addresses.sort_unstable(); }\n            // Do not print private addresses or backing identities even on failure.\n            assert!(actual == expected, \"reverse index mismatch\");\n            assert_eq!(total, bytes);\n            assert_eq!(expected.len(), unique);\n        };\n        let check = |bytes: usize, unique: usize| {\n            oracle(bytes, unique);\n            let sample = mapping_diagnostic_snapshot();\n            if enabled {\n                let s = sample.expect(\"coherent completed mapping\");\n                assert_eq!(s.view_bytes, bytes as u64);\n                assert_eq!(s.unique_pages, unique as u64);\n                assert_eq!(s.alias_bytes, (bytes - unique * PAGE) as u64);\n            } else {\n                assert_eq!(sample, Err(Unavailable::Disabled));\n            }\n        };\n        assert_eq!(mapping_diagnostic_snapshot(), Err(if enabled { Unavailable::Initial } else { Unavailable::Disabled }));\n        let pages = allocate(2);\n        let reserve = || XMemVirtualAlloc(std::ptr::null_mut(),2*PAGE,MEM_RESERVE | PAGES_64K,0,PAGE_READWRITE);\n        let (a,b)=(reserve(),reserve());\n        assert!(!a.is_null() && !b.is_null());\n        assert_eq!(XMemMapPhysicalPages(a,2,pages.as_ptr()),a);\n        check(2*PAGE,2);\n        let second = a.wrapping_byte_add(PAGE);\n        assert!(map_alias(b as u64,second as u64,PAGE as u64));\n        check(3*PAGE,2);\n        unsafe { second.cast::<u8>().write(42); assert_eq!(b.cast::<u8>().read(),42); }\n        let before_failure = mapping_diagnostic_snapshot();\n        {\n            let mut physical=physical();\n            let _changing=victory_gpu::title_memory_remapping();\n            assert!(!unmap_with(&mut physical,b as usize,PAGE,|_| false));\n        }\n        assert_eq!(mapping_diagnostic_snapshot(), before_failure);\n        check(3*PAGE,2);\n        let before_free = mapping_diagnostic_snapshot();\n        assert_eq!(XMemFreePhysicalPages(2,pages.as_ptr()),1);\n        assert_eq!(mapping_diagnostic_snapshot(), before_free);\n        { let guard = physical(); assert!(!guard.mapping_observation.needs_finish()); }\n        assert_eq!(mapping_diagnostic_snapshot(), before_free);\n        check(3*PAGE,2);\n        assert_eq!(XMemMapPhysicalPages(a,1,std::ptr::null()),a);\n        check(2*PAGE,1);\n        assert_eq!(XMemMapPhysicalPages(second,1,std::ptr::null()),second);\n        check(PAGE,1);\n        assert_eq!(unsafe { b.cast::<u8>().read() },42);\n        assert!(map_alias(b as u64,0,PAGE as u64));\n        check(0,0);\n        // True interior split: retain both neighboring views and their bytes.\n        let three = allocate(3);\n        let c = XMemVirtualAlloc(std::ptr::null_mut(),3*PAGE,MEM_RESERVE | PAGES_64K,0,PAGE_READWRITE);\n        assert!(!c.is_null());\n        let middle = c.wrapping_byte_add(PAGE);\n        let last = c.wrapping_byte_add(2*PAGE);\n        // The public mapper may fall back to three separate views.\n        // Exercise the real multi-page map directly for this split proof.\n        {\n            let mut g = physical();\n            let _changing = victory_gpu::title_memory_remapping();\n            let first = g.pages.get(&three[0]).unwrap().clone();\n            for (k, number) in three.iter().enumerate() {\n                let part = g.pages.get(number).unwrap();\n                assert!(Arc::ptr_eq(&first.section, &part.section));\n                assert_eq!(part.index, first.index + k);\n            }\n            assert!(map(&mut g,c as usize,3*PAGE,first));\n            assert_eq!(g.views.len(),1);\n            assert_eq!(g.views.get(&(c as usize)).unwrap().0,3*PAGE);\n        }\n        check(3*PAGE,3);\n        unsafe { c.cast::<u8>().write(19); last.cast::<u8>().write(73); }\n        assert_eq!(XMemMapPhysicalPages(middle,1,std::ptr::null()),middle);\n        {\n            let g = physical();\n            assert_eq!(g.views.len(),2);\n            assert_eq!(g.views.get(&(c as usize)).unwrap().0,PAGE);\n            assert_eq!(g.views.get(&(last as usize)).unwrap().0,PAGE);\n            assert!(!g.views.contains_key(&(middle as usize)));\n        }\n        check(2*PAGE,2);\n        unsafe { assert_eq!(c.cast::<u8>().read(),19); assert_eq!(last.cast::<u8>().read(),73); }\n        // First host removal is real; the later one is a deterministic\n        // refusal. Never return true for a still-live OS view.\n        {\n            let mut physical = physical();\n            let _changing = victory_gpu::title_memory_remapping();\n            let mut calls = 0;\n            assert!(!unmap_with(&mut physical,c as usize,3*PAGE,|at| {\n                calls += 1;\n                if calls == 1 {\n                    assert_eq!(at,c as usize);\n                    unsafe {\n                        UnmapViewOfFile2(GetCurrentProcess(),\n                            MEMORY_MAPPED_VIEW_ADDRESS { Value: at as *mut c_void },\n                            MEM_PRESERVE_PLACEHOLDER) != 0\n                    }\n                } else {\n                    assert_eq!(at,last as usize);\n                    false\n                }\n            }));\n            assert_eq!(calls,2);\n            assert_eq!(physical.views.len(),1);\n            assert_eq!(physical.views.get(&(last as usize)).unwrap().0,PAGE);\n            assert!(!physical.views.contains_key(&(c as usize)));\n        }\n        check(PAGE,1);\n        assert_eq!(unsafe { last.cast::<u8>().read() },73);\n        assert_eq!(XMemMapPhysicalPages(c,3,std::ptr::null()),c);\n        check(0,0);\n        assert_eq!(XMemFreePhysicalPages(3,three.as_ptr()),1);\n        // Test sticky unknown publication explicitly; not an OS failure injection.\n        { physical().mapping_observation.unknown(); }\n        if enabled { assert_eq!(mapping_diagnostic_snapshot(),Err(Unavailable::Invalid)); }\n        let again=allocate(1);\n        assert_eq!(XMemMapPhysicalPages(a,1,again.as_ptr()),a);\n        oracle(PAGE,1);\n        assert_eq!(mapping_diagnostic_snapshot(),Err(if enabled { Unavailable::Invalid } else { Unavailable::Disabled }));\n        assert_eq!(XMemMapPhysicalPages(a,1,std::ptr::null()),a);\n        assert_eq!(XMemFreePhysicalPages(1,again.as_ptr()),1);\n        oracle(0,0);\n    }\n\n    // Each corruption is isolated in a fresh process so sticky invalidity\n    // cannot hide a missing detection in another case. Only synthetic\n    // reverse metadata changes; the real host view is removed normally.\n    fn mapping_diagnostic_reverse_anomaly(kind: u8) {\n        use mapping_diagnostic::Unavailable;\n        let mode = std::env::var(\"VICTORY_MAPPING_DIAGNOSTIC\").expect(\"explicit mode\");\n        assert!(matches!(mode.as_str(), \"0\" | \"1\"));\n        let enabled = mode == \"1\";\n        assert_eq!(mapping_diagnostic_on(), enabled);\n        let pages = allocate(1);\n        let a = XMemVirtualAlloc(std::ptr::null_mut(),PAGE,MEM_RESERVE | PAGES_64K,0,PAGE_READWRITE);\n        assert!(!a.is_null());\n        assert_eq!(XMemMapPhysicalPages(a,1,pages.as_ptr()),a);\n        if enabled {\n            assert_eq!(mapping_diagnostic_snapshot().unwrap().view_bytes,PAGE as u64);\n        }\n        {\n            let mut g = physical();\n            let key = g.views.get(&(a as usize)).unwrap().1.key(0);\n            assert_eq!(g.shown.get(&key).unwrap().as_slice(), &[a as usize]);\n            match kind {\n                0 => { assert!(g.shown.remove(&key).is_some()); }\n                1 => { g.shown.get_mut(&key).unwrap().clear(); }\n                2 => { g.shown.get_mut(&key).unwrap().push(a as usize); }\n                _ => unreachable!(),\n            }\n        }\n        // Actual unmap must keep its baseline return and cleanup semantics.\n        assert_eq!(XMemMapPhysicalPages(a,1,std::ptr::null()),a);\n        let expected = Err(if enabled { Unavailable::Invalid } else { Unavailable::Disabled });\n        assert_eq!(mapping_diagnostic_snapshot(),expected);\n        { let g = physical(); assert!(g.views.is_empty() && g.shown.is_empty()); }\n        // A later valid-looking map cannot clear source uncertainty.\n        assert_eq!(XMemMapPhysicalPages(a,1,pages.as_ptr()),a);\n        assert_eq!(mapping_diagnostic_snapshot(),expected);\n        assert_eq!(XMemMapPhysicalPages(a,1,std::ptr::null()),a);\n        assert_eq!(XMemFreePhysicalPages(1,pages.as_ptr()),1);\n    }\n\n    #[test]\n    #[ignore = \"isolated reverse-index anomaly\"]\n    fn mapping_diagnostic_missing_reverse_key() { mapping_diagnostic_reverse_anomaly(0); }\n\n    #[test]\n    #[ignore = \"isolated reverse-index anomaly\"]\n    fn mapping_diagnostic_missing_reverse_address() { mapping_diagnostic_reverse_anomaly(1); }\n\n    #[test]\n    #[ignore = \"isolated reverse-index anomaly\"]\n    fn mapping_diagnostic_duplicate_reverse_address() { mapping_diagnostic_reverse_anomaly(2); }\n\n    #[test]\n    fn physical_pages_map_alias_and_unmap() {", 1),
)

def transform(source):
    for old, new, count in REPLACEMENTS:
        if source.count(old) != count:
            raise ValueError("Unexpected mapping diagnostic anchor: " + old[:80])
        source = source.replace(old, new, count)
    return source

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("checkout", type=Path)
    args = parser.parse_args()
    path = args.checkout / PATH
    module = path.with_name("xmem_mapping_diagnostic.rs")
    try:
        if module.exists():
            raise ValueError("Mapping diagnostic module already installed")
        source = transform(path.read_text(encoding="utf-8"))
        helper = (Path(__file__).resolve().parents[1] / "probes" / "mapping_diagnostic.rs").read_text(encoding="utf-8")
        path.write_text(source, encoding="utf-8")
        module.write_text(helper, encoding="utf-8")
    except (OSError, ValueError) as exc:
        parser.exit(1, f"Mapping diagnostic preparation failed: {exc}\n")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
